import{_ as d,o as r,c as o,a3 as e}from"./chunks/framework.qCVWde4n.js";const b=JSON.parse('{"title":"术语表","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":1791133906000}'),s={name:"glossary.md"};function n(a,t,g,c,h,l){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>文档里出现的名词，一句话解释。按类别分组。</p><h2 id="框架与-mod" tabindex="-1">框架与 Mod <a class="header-anchor" href="#框架与-mod" aria-label="Permalink to &quot;框架与 Mod&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>说明</th></tr></thead><tbody><tr><td><strong>Mod</strong></td><td>一个文件夹 + 一个 <code>mod.json</code>，用来改数值、加舰船、换模型。放在游戏私有目录的 <code>mods/</code> 下</td></tr><tr><td><strong>mod.json</strong></td><td>Mod 的核心文件，UTF-8 无 BOM。里面写名号、舰船、编队、参数</td></tr><tr><td><strong>参数</strong></td><td>框架统一管理的可调数值，目前 23 个，如 <code>gun.damageMul</code></td></tr><tr><td><strong>参数键</strong></td><td>参数的名字，形如 <code>组.动作</code>（<code>gun.damageMul</code>）</td></tr><tr><td><strong>倍率</strong></td><td>参数改的不是绝对值而是「原值 × 倍率」，<code>1.0</code> = 原版</td></tr><tr><td><strong>软边界 / 硬边界</strong></td><td>软 = 滑块推荐范围；硬 = 框架接受的绝对范围，超出会被<strong>静默截断</strong></td></tr><tr><td><strong>priority</strong></td><td>Mod 加载顺序，越小越先加载。同值时按名字排</td></tr><tr><td><strong>挂钩（hook）</strong></td><td>在游戏源码里插一段我们的代码</td></tr></tbody></table><h2 id="游戏内界面" tabindex="-1">游戏内界面 <a class="header-anchor" href="#游戏内界面" aria-label="Permalink to &quot;游戏内界面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>说明</th></tr></thead><tbody><tr><td><strong>小u</strong></td><td>游戏内的半透明悬浮窗（作者署名）。点它开控制台面板</td></tr><tr><td><strong>控制台</strong></td><td>「小u」点开的界面，6 个标签页：参数 / Mod / 存档 / 日志 / 状态 / 帮助</td></tr><tr><td><strong>收起成小圆点</strong></td><td>把「小u」缩成一个很小的点，基本不挡视线</td></tr><tr><td><strong>三指手势</strong></td><td>三指同时按住屏幕，强制唤起「小u」（防收不到抬手事件）</td></tr><tr><td><strong>倍速</strong></td><td>游戏时间快慢（<code>x1</code>/<code>x2</code>/<code>x3</code>）。仅本次会话有效，重启回 <code>x1</code></td></tr><tr><td><strong>偏离清单</strong></td><td>「状态」页里列出所有当前值 ≠ 默认值的参数</td></tr></tbody></table><h2 id="游戏内机制" tabindex="-1">游戏内机制 <a class="header-anchor" href="#游戏内机制" aria-label="Permalink to &quot;游戏内机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>说明</th></tr></thead><tbody><tr><td><strong>威望 / Renown</strong></td><td>游戏内的货币，用来解锁舰船</td></tr><tr><td><strong>舰级（class）</strong></td><td>一类船，如「Bismarck」。下面可挂多艘具体舰只</td></tr><tr><td><strong>classID</strong></td><td>舰级的内部编号。<strong>等于它在数组里的下标</strong>，由框架自动算</td></tr><tr><td><strong>舰种代号</strong></td><td><code>BB</code> 战列 / <code>CA</code> 重巡 / <code>CL</code> 轻巡 / <code>DD</code> 驱逐 / <code>SS</code> 潜艇 / <code>CV</code> 航母 等</td></tr><tr><td><strong>编队（fleet）</strong></td><td>一次「自定义战斗」里的舰船组合</td></tr><tr><td><strong>热座对战</strong></td><td>同一台手机上两人轮流操作。<strong>不是联网对战</strong></td></tr><tr><td><strong>刺猬炮 / Hedgehog</strong></td><td>一种反潜武器（前置发射的深水炸弹）</td></tr><tr><td><strong>乌贼炮 / Squid</strong></td><td>另一种反潜武器</td></tr><tr><td><strong>深水炸弹 / Depth Charge</strong></td><td>反潜用的炸弹</td></tr></tbody></table><h2 id="技术名词" tabindex="-1">技术名词 <a class="header-anchor" href="#技术名词" aria-label="Permalink to &quot;技术名词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>说明</th></tr></thead><tbody><tr><td><strong>DLL</strong></td><td>游戏的核心程序文件（<code>Assembly-CSharp.dll</code>），这个框架会把它整个重编译一遍</td></tr><tr><td><strong>重编译</strong></td><td>把 DLL 反编译成源码 → 加代码 → 再编译回去（不是运行时织入）</td></tr><tr><td><strong>Assembly-CSharp.dll</strong></td><td>Unity 游戏的主程序 DLL，本项目重编译的目标</td></tr><tr><td><strong>AssetBundle / .unity3d</strong></td><td>Unity 的资源包格式，用来装自制模型</td></tr><tr><td><strong>不压缩打包</strong></td><td><code>UncompressedAssetBundle</code>。<strong>必须</strong>，否则 Android 上读不了</td></tr><tr><td><strong>prefab</strong></td><td>Unity 里的「预制件」，一个完整的可用对象（如一整艘船）</td></tr><tr><td><strong>组件 / component</strong></td><td>挂在 prefab 上的脚本，如 <code>Vessel</code> / <code>DamageSystem</code></td></tr><tr><td><strong>CGI 式 #US 堆</strong></td><td>DLL 里存「用户字符串」（界面文本）的区段，UTF-16 编码</td></tr><tr><td><strong>#Strings 堆</strong></td><td>DLL 里存「类型名」的区段，UTF-8 编码</td></tr><tr><td><strong>落盘</strong></td><td>把数据写进文件，重启后还在</td></tr><tr><td><strong>try/catch</strong></td><td>异常兜底——出错就记日志然后继续，绝不崩游戏</td></tr></tbody></table><h2 id="相关平台" tabindex="-1">相关平台 <a class="header-anchor" href="#相关平台" aria-label="Permalink to &quot;相关平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>说明</th></tr></thead><tbody><tr><td><strong>Mod 仓库</strong></td><td>网页版作品集散地：<code>https://atlanticfleet.asia/mods/</code></td></tr><tr><td><strong>分享码</strong></td><td><code>AFMOD1:xxxx</code> 格式的字符串，编码了一整个 Mod，用来互传</td></tr><tr><td><strong>_sharein</strong></td><td>放分享码 <code>.txt</code> 文件自动导入的目录</td></tr><tr><td><strong>AFMOD_profile.json</strong></td><td>玩家本地档案（代号 / 威望 / 战绩）</td></tr><tr><td><strong>AFMOD_settings.json</strong></td><td>面板上改的参数覆盖值（<strong>实验性参数不跨会话</strong>）</td></tr><tr><td><strong>AFMOD_log.txt</strong></td><td>落盘的运行日志，游戏关掉也不丢</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>这些功能怎么用 → <a href="/AtlanticFleetSite/docs/features/start">功能接入</a></li><li>遇到问题 → <a href="/AtlanticFleetSite/docs/faq">常见问题</a></li><li>深入原理 → <a href="/AtlanticFleetSite/docs/technical">技术细节</a></li></ul>',14)])])}const u=d(s,[["render",n]]);export{b as __pageData,u as default};
